from collections import defaultdict

def longestKSubstr(S, K):
    if K == 0 or len(S) < K:
        return -1

    freq = defaultdict(int)
    left = 0
    max_len = 0
    unique = 0

    for right in range(len(S)):
        if freq[S[right]] == 0:
            unique += 1
        freq[S[right]] += 1

        while unique > K:
            freq[S[left]] -= 1
            if freq[S[left]] == 0:
                unique -= 1
            left += 1

        if unique == K:
            max_len = max(max_len, right - left + 1)

